(\lambda y:B.t)[x:=s]=
\begin{cases}
\lambda y:B[x:=s].t,&y=x,\\
\lambda y:B[x:=s].t[x:=s],&y\ne x,\ y\notin\operatorname{FV}^{x}_{\mathsf F}(s),\\
\lambda z:B[x:=s].(t[y:=z])[x:=s],&y\ne x,\ y\in\operatorname{FV}^{x}_{\mathsf F}(s),
\end{cases}

\{y:B\mid\varphi\}[x:=s]=
\begin{cases}
\{y:B[x:=s]\mid\varphi\},&y=x,\\
\{y:B[x:=s]\mid\varphi[x:=s]\},&y\ne x,\ y\notin\operatorname{FV}^{x}_{\mathsf F}(s),\\
\{z:B[x:=s]\mid(\varphi[y:=z])[x:=s]\},&y\ne x,\ y\in\operatorname{FV}^{x}_{\mathsf F}(s),
\end{cases}

(\forall y:A.\varphi)[x:=s]=\begin{cases}
\forall y:A[x:=s].\varphi,&y=x,\\
\forall y:A[x:=s].\varphi[x:=s],&y\ne x,\ y\notin FV^x(s),\\
\forall z:A[x:=s].(\varphi[y:=z])[x:=s],&y\ne x,\ y\in FV^x(s),
\end{cases}

(\forall Y:K.B)[X:=A]=
\begin{cases}
\forall Y:K.B,&Y=X,\\
\forall Y:K.B[X:=A],&Y\ne X,\ Y\notin\operatorname{FV}_X(A),\\
\forall Z:K.(B[Y:=Z])[X:=A],&Y\ne X,\ Y\in\operatorname{FV}_X(A),
\end{cases}

(\Lambda Y:K.t)[X:=A]=
\begin{cases}
\Lambda Y:K.t,&Y=X,\\
\Lambda Y:K.t[X:=A],&Y\ne X,\ Y\notin\operatorname{FV}^{X}_{\mathsf F}(A),\\
\Lambda Z:K.(t[Y:=Z])[X:=A],&Y\ne X,\ Y\in\operatorname{FV}^{X}_{\mathsf F}(A),
\end{cases}

\begin{array}{c|l}
\mathsf{SRefl}&\langle\rangle\Rightarrow A\preceq_\Gamma A\\
\mathsf{SAlpha}&\langle\rangle\Rightarrow B\preceq_\Gamma A\quad(Q\in\mathsf{AlphaCert}(B,A))\\
\mathsf{STrans}&\langle B\preceq_\Gamma C,C\preceq_\Gamma A\rangle\Rightarrow B\preceq_\Gamma A\\
\mathsf{SArr}&\langle A_1\preceq_\Gamma B_1,B_2\preceq_\Gamma A_2\rangle\Rightarrow(B_1\to_\rho B_2)\preceq_\Gamma(A_1\to_\eta A_2)\\
\mathsf{SAll}&\langle B[X:=Z]\preceq_{\Gamma,Z:K}A[Y:=Z]\rangle\Rightarrow(\forall X:K.B)\preceq_\Gamma(\forall Y:K.A)\\
\mathsf{SForget}&\langle\rangle\Rightarrow\{x:B\mid\varphi\}\preceq_\Gamma B\\
\mathsf{SRef}&\langle B\preceq_\Gamma A\rangle\Rightarrow B\preceq_\Gamma\{x:A\mid\varphi\}
\end{array}
